/**
 * The name a product's image carries across a navigation.
 *
 * `view-transition-name` takes a CSS custom-ident, which cannot start with a
 * digit and cannot contain most punctuation. Slugs are generated by slugify so
 * they are already kebab-case, but they are also user-derived, and a slug like
 * "2024-planner" would produce an invalid ident that the browser drops without
 * complaint — the morph would just quietly never happen.
 *
 * The `product-` prefix guarantees a leading letter and namespaces it against
 * any other named element on the page.
 */
export function productMorphName(slug: string): string {
  return `product-${slug.replace(/[^a-zA-Z0-9_-]/g, "-")}`;
}
